import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { motion } from 'framer-motion';
import './ProfileCard.css';
import profileImage from '../../IMG_8086.jpg';
import hoverSound from '../../sounds/hover.mp3';
import clickSound from '../../sounds/click.mp3';
import backgroundMusic from '../../sounds/background.mp3';
import ExpandedView from './ExpandedView';

// Custom hook for animation timing
const useAnimationConfig = () => {
  return {
    duration: 0.5,
    ease: [0.43, 0.13, 0.23, 0.96], // Custom easeInOut curve
  };
};

// Particle component for the animation effect
const Particle = ({ index }) => {
  const randomOffset = () => (Math.random() - 0.5) * 100;

  return (
    <motion.div
      className="particle"
      initial={{ 
        x: 0, 
        y: 0, 
        opacity: 0,
        scale: 0 
      }}
      animate={{ 
        x: randomOffset(), 
        y: randomOffset(), 
        opacity: [0, 0.8, 0],
        scale: [0, 1, 0]
      }}
      transition={{ 
        duration: 2,
        repeat: Infinity,
        repeatType: "loop",
        delay: index * 0.1,
        ease: "easeInOut"
      }}
    />
  );
};

const ProfileCard = () => {
  const [isHovered, setIsHovered] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [windowSize, setWindowSize] = useState({
    width: typeof window !== 'undefined' ? window.innerWidth : 0,
    height: typeof window !== 'undefined' ? window.innerHeight : 0,
  });
  const animationConfig = useAnimationConfig();

  // Audio refs
  const hoverAudioRef = useRef(new Audio(hoverSound));
  const clickAudioRef = useRef(new Audio(clickSound));
  const backgroundAudioRef = useRef(new Audio(backgroundMusic));

  // Initialize background music
  useEffect(() => {
    backgroundAudioRef.current.volume = 0.2;
    backgroundAudioRef.current.loop = true;

    // Start playing background music when component mounts
    const playBackgroundMusic = async () => {
      try {
        await backgroundAudioRef.current.play();
      } catch (error) {
        console.log('Background music play failed:', error);
      }
    };

    playBackgroundMusic();

    // Cleanup function to stop music when component unmounts
    return () => {
      backgroundAudioRef.current.pause();
      backgroundAudioRef.current.currentTime = 0;
    };
  }, []);

  // Handle window resize
  useEffect(() => {
    const handleResize = () => {
      setWindowSize({
        width: window.innerWidth,
        height: window.innerHeight,
      });
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Handle hover sound
  useEffect(() => {
    if (isHovered) {
      hoverAudioRef.current.currentTime = 0;
      hoverAudioRef.current.volume = 0.3;
      hoverAudioRef.current.play().catch(error => console.log('Audio play failed:', error));
    }
  }, [isHovered]);

  // Memoized click handler
  const handleClick = useCallback(() => {
    clickAudioRef.current.currentTime = 0;
    clickAudioRef.current.volume = 0.5;
    clickAudioRef.current.play().catch(error => console.log('Audio play failed:', error));
    setIsExpanded(true);
  }, []);

  // Memoized close handler
  const handleClose = useCallback(() => {
    setIsExpanded(false);
  }, []);

  // Generate particles
  const particles = Array.from({ length: 10 }).map((_, index) => (
    <Particle key={index} index={index} />
  ));

  const profileData = {
    name: "Ayomide Abioye",
    title: "UI/UX Designer | Front-End Developer",
    bio: "Passionate about creating beautiful, intuitive, and performant user interfaces. Experienced in React, TypeScript, and modern web technologies.",
    image: profileImage,
    email: "ayozzabioye@gmail.com",
    phone: "647-825-7513",
    location: "Toronto, Canada",
    portfolio: [
      {
        title: "Interactive Profile Card",
        description: "A modern profile card with laser animations and interactive elements built with React and Framer Motion.",
        tags: ["React", "Framer Motion", "CSS Animations"],
        link: "https://github.com/yourusername/profile-card"
      },
      {
        title: "Portfolio Website",
        description: "Personal portfolio website showcasing my projects and skills.",
        tags: ["React", "Next.js", "Tailwind CSS"],
        link: "https://ayomideabioye.com"
      },
      {
        title: "Project 3",
        description: "Description of your third project",
        tags: ["TypeScript", "Node.js", "MongoDB"],
        link: "https://github.com/yourusername/project3"
      }
    ],
    socialLinks: [
      {
        name: "GitHub",
        icon: "📦",
        url: "https://github.com/yourusername"
      },
      {
        name: "LinkedIn",
        icon: "💼",
        url: "https://linkedin.com/in/yourusername"
      },
      {
        name: "Twitter",
        icon: "🐦",
        url: "https://twitter.com/yourusername"
      }
    ]
  };

  return (
    <div className="profile-card-container">
      {/* Full screen laser beams that activate on hover */}
      <div className="laser-beam beam-1"></div>
      <div className="laser-beam beam-2"></div>
      <div className="laser-beam beam-3"></div>
      <div className="laser-beam beam-4"></div>

      <motion.div
        className="profile-card"
        whileHover={{ scale: 1.02 }}
        onClick={handleClick}
        onHoverStart={() => setIsHovered(true)}
        onHoverEnd={() => setIsHovered(false)}
        initial={{ y: 20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 0.5, delay: 0.2 }}
      >
        {/* Laser beams */}
        <div className="laser-beam top" />
        <div className="laser-beam bottom" />

        <motion.div 
          className="profile-image-container"
          whileHover={{ scale: 1.05 }}
          transition={{ duration: 0.3 }}
        >
          <img 
            src={profileData.image} 
            alt={profileData.name} 
            className="profile-image" 
          />
          {isHovered && (
            <motion.div 
              className="image-overlay"
              initial={{ opacity: 0 }}
              animate={{ opacity: 0.3 }}
              transition={{
                duration: animationConfig.duration,
                ease: animationConfig.ease
              }}
            />
          )}
          {isHovered && (
            <div className="particles-container">
              {particles}
            </div>
          )}
        </motion.div>

        <motion.h2 
          className="profile-name"
          initial={{ y: 20, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.5, delay: 0.3 }}
        >
          {profileData.name}
        </motion.h2>

        <motion.p 
          className="profile-title"
          initial={{ y: 20, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.5, delay: 0.4 }}
        >
          {profileData.title}
        </motion.p>

        <motion.div 
          className="profile-location"
          initial={{ y: 20, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.5, delay: 0.5 }}
        >
          <span>📍</span> {profileData.location}
        </motion.div>

        <motion.div 
          className="profile-hint"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.5, delay: 0.6 }}
        >
          Click to view full profile
        </motion.div>
      </motion.div>

      <ExpandedView
        isOpen={isExpanded}
        onClose={handleClose}
        profileData={profileData}
      />
    </div>
  );
};

export default React.memo(ProfileCard);
